package main

import (
	"fmt"
	"time"
)

func main() {
	result := make(chan int)

	go func() {
		time.Sleep(200 * time.Millisecond) // slower than our timeout
		result <- 42
	}()

	select {
	case v := <-result:
		fmt.Println("got result:", v)
	case <-time.After(100 * time.Millisecond): // fires first
		fmt.Println("timed out waiting for result")
	}
}

package main

import (
	"context"
	"fmt"
	"time"
)

func worker(ctx context.Context, jobs <-chan int) {
	for {
		select {
		case <-ctx.Done(): // cancellation signal
			fmt.Println("worker stopping:", ctx.Err())
			return
		case j, ok := <-jobs:
			if !ok { // channel closed and drained
				fmt.Println("jobs closed")
				return
			}
			fmt.Println("processing job", j)
		}
	}
}

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 50*time.Millisecond)
	defer cancel()

	jobs := make(chan int)
	go worker(ctx, jobs)

	jobs <- 1
	jobs <- 2
	time.Sleep(100 * time.Millisecond) // let the context expire
}
